// Extract request ID from topic
const parts = msg.topic.split('/');
const requestId = parts[parts.length - 1];

msg.rpcRequestId = requestId;
msg.rpcResponseTopic = 'v1/devices/me/rpc/response/' + requestId;

const rpc = msg.payload || {};
msg.rpcMethod = rpc.method;
msg.rpcParams = rpc.params || {};

// Valid flow management methods
const validMethods = [
    'getFlows', 'setFlows', 'deleteFlows',
    'addFlow', 'updateFlow', 'removeFlow'
];

if (!validMethods.includes(msg.rpcMethod)) {
    return null;
}

node.status({fill: 'blue', shape: 'dot', text: msg.rpcMethod});
return msg;

// Get flows from RPC params
const flows = msg.rpcParams.flows || msg.rpcParams;

if (!flows || !Array.isArray(flows)) {
    msg.payload = {
        success: false,
        error: 'Invalid flows data. Expected array.'
    };
    msg.statusCode = 400;
    return [null, msg];
}

msg.payload = flows;
msg.headers = {
    'Content-Type': 'application/json',
    'Node-RED-Deployment-Type': msg.rpcParams.deploymentType || 'full'
};

return [msg, null];

// Delete all flows by posting empty array
msg.payload = [];
msg.headers = {
    'Content-Type': 'application/json',
    'Node-RED-Deployment-Type': 'full'
};
return msg;

// Add a single flow (tab with its nodes)
// params.flow = { id, label, nodes: [...] }

const flowData = msg.rpcParams.flow;

if (!flowData) {
    msg.payload = {
        success: false,
        error: 'Missing flow parameter. Expected: { flow: { id, label, nodes: [...] } }'
    };
    msg.statusCode = 400;
    return [null, msg];
}

// Build the flow structure for POST /flow
// Node-RED expects: { id, label, nodes: [...], configs: [...] }
msg.payload = {
    id: flowData.id || undefined,
    label: flowData.label || 'New Flow',
    disabled: flowData.disabled || false,
    info: flowData.info || '',
    nodes: flowData.nodes || [],
    configs: flowData.configs || []
};

msg.headers = {
    'Content-Type': 'application/json'
};

return [msg, null];

// Update a single flow by ID
// params.id = flow tab id
// params.flow = { label, nodes: [...] }

const flowId = msg.rpcParams.id;
const flowData = msg.rpcParams.flow;

if (!flowId) {
    msg.payload = {
        success: false,
        error: 'Missing id parameter'
    };
    msg.statusCode = 400;
    return [null, msg];
}

if (!flowData) {
    msg.payload = {
        success: false,
        error: 'Missing flow parameter'
    };
    msg.statusCode = 400;
    return [null, msg];
}

msg.url = 'http://localhost:1880/flow/' + flowId;
msg.payload = {
    id: flowId,
    label: flowData.label,
    disabled: flowData.disabled || false,
    info: flowData.info || '',
    nodes: flowData.nodes || [],
    configs: flowData.configs || []
};

msg.headers = {
    'Content-Type': 'application/json'
};

return [msg, null];

// Remove a single flow by ID
// params.id = flow tab id to delete

const flowId = msg.rpcParams.id;

if (!flowId) {
    msg.payload = {
        success: false,
        error: 'Missing id parameter. Expected: { id: "flow_tab_id" }'
    };
    msg.statusCode = 400;
    return [null, msg];
}

// Protect critical flows from deletion
const protectedFlows = ['rpc_flow_manager_tab'];
if (protectedFlows.includes(flowId)) {
    msg.payload = {
        success: false,
        error: 'Cannot delete protected flow: ' + flowId
    };
    msg.statusCode = 403;
    return [null, msg];
}

msg.url = 'http://localhost:1880/flow/' + flowId;
msg.headers = {
    'Content-Type': 'application/json'
};

return [msg, null];

const method = msg.rpcMethod;
const statusCode = msg.statusCode || 200;

let response = {};

switch(method) {
    case 'getFlows':
        response = {
            success: true,
            flowCount: Array.isArray(msg.payload) ? msg.payload.length : 0,
            flows: msg.payload
        };
        break;

    case 'setFlows':
        response = {
            success: statusCode >= 200 && statusCode < 300,
            message: 'Flows deployed successfully'
        };
        break;

    case 'deleteFlows':
        response = {
            success: statusCode >= 200 && statusCode < 300,
            message: 'All flows deleted'
        };
        break;

    case 'addFlow':
        response = {
            success: statusCode >= 200 && statusCode < 300,
            message: 'Flow added successfully',
            flowId: msg.payload ? msg.payload.id : null
        };
        break;

    case 'updateFlow':
        response = {
            success: statusCode >= 200 && statusCode < 300,
            message: 'Flow updated successfully',
            flowId: msg.rpcParams.id
        };
        break;

    case 'removeFlow':
        response = {
            success: statusCode >= 200 && statusCode < 300,
            message: 'Flow removed successfully',
            flowId: msg.rpcParams.id
        };
        break;

    default:
        response = {
            success: false,
            error: 'Unknown method'
        };
}

if (statusCode >= 400) {
    response.success = false;
    response.error = msg.payload || 'Operation failed';
    response.statusCode = statusCode;
}

msg.payload = response;
msg.topic = msg.rpcResponseTopic;

node.status({
    fill: response.success ? 'green' : 'red',
    shape: 'dot',
    text: method + ': ' + (response.success ? 'OK' : 'FAIL')
});

return msg;

info:
## Available Methods

### Bulk Operations
- **getFlows**: Get all flows
- **setFlows**: Replace ALL flows
- **deleteFlows**: Delete ALL flows

### Single Flow Operations (Recommended)
- **addFlow**: Add one flow tab
- **updateFlow**: Update one flow tab
- **removeFlow**: Delete one flow tab

## Examples

### addFlow
```json
{
  "method": "addFlow",
  "params": {
    "flow": {
      "label": "My New Flow",
      "nodes": [...],
      "configs": [...]
    }
  }
}
```

### updateFlow
```json
{
  "method": "updateFlow",
  "params": {
    "id": "flow_tab_id",
    "flow": {
      "label": "Updated Label",
      "nodes": [...]
    }
  }
}
```

### removeFlow
```json
{
  "method": "removeFlow",
  "params": {
    "id": "flow_tab_id"
  }
}
```
